import { registerConsoleShortcuts } from "./390.js";
function pluginQRCode(options) {
    const defaultPluginOptions = {
        schema: (url)=>({
                http: url
            })
    };
    const { schema } = Object.assign({}, defaultPluginOptions, options);
    return {
        name: 'lynx:rsbuild:qrcode',
        pre: [
            'lynx:rsbuild:api'
        ],
        setup (api) {
            api.onAfterStartProdServer(async ({ environments, port })=>{
                await main(getEntries(environments), port);
            });
            let printedQRCode = false;
            api.onDevCompileDone(async ({ stats, environments })=>{
                if (!api.context.devServer) return;
                if (stats.hasErrors()) return;
                if (printedQRCode) return;
                printedQRCode = true;
                await main(getEntries(environments), api.context.devServer.port);
            });
            function getEntries(environments) {
                return api.useExposed(Symbol.for('rspeedy.env.entries'))?.entries ?? environments?.['lynx']?.entry;
            }
            async function main(entries, port) {
                if (!entries) return;
                const entriesArray = Object.keys(entries);
                if (0 === entriesArray.length) return;
                const unregister = await registerConsoleShortcuts({
                    entries: entriesArray,
                    api,
                    port,
                    schema
                });
                api.onCloseDevServer(unregister);
            }
        }
    };
}
export { pluginQRCode };
